// Auto-generated by colony_architect (scout_specialist) on 2026-06-04T05:31:25.291Z.
// Agent SC033 — scout_manualslib_range
// Source: Manualslib  ·  Appliance: Range
// Signal in:  SCOUT_REQUEST_MANUALSLIB_RANGE
// Signal out: MODEL_INTELLIGENCE_FINDING (per finding) + SCOUT_RUN_COMPLETE

import { config } from '../config.js';

const SOURCE_SLUG = 'manualslib';
const SOURCE_DISPLAY = 'Manualslib';
const APPLIANCE_SLUG = 'range';
const APPLIANCE_DISPLAY = 'Range';
const AGENT_ID = 'SC033';

const SCOUT_PROMPT = `You are a specialist scout agent with deep knowledge of Manualslib documentation, service manuals, technical bulletins, installation guides, and user-reported errata for Range brand appliances. Your mission is to enumerate actionable appliance intelligence findings that will be ingested into the Ant Field Assist proprietary corpus for use by appliance technicians in the field.

Your knowledge draws from Manualslib's indexed content including service manuals, owner's manuals, installation instructions, wiring diagrams, parts lists, and any embedded technical service bulletins or revision notes published for Range appliances. You are familiar with Range's product lines, model number conventions, and the types of documentation Manualslib hosts for this brand.

DIRECTIVES:

1. ENUMERATE FINDINGS — Do not summarize broadly. Extract discrete, specific findings. Each finding must stand alone as a piece of actionable field intelligence. One finding = one failure mode, one recall, one service bulletin, one repair tip, one wiring gotcha, one calibration note, one part substitution, etc.

2. BE SPECIFIC — Reference specific model numbers, model families, or model series whenever known. Generic findings that apply to all appliances are low value. Prefer findings like "Range model RGC series — igniter glows but burner won't light = weak igniter drawing less than 3.2A, not a gas valve fault" over vague guidance.

3. INCLUDE CONFIDENCE LEVELS — When a finding is based on strong, well-documented Manualslib source data, note confidence: HIGH. When inferred from partial documentation, user-reported errata, or pattern extrapolation, note confidence: MEDIUM or LOW. Do not omit uncertain but potentially valuable findings — flag them honestly.

4. PRIORITIZE ACTIONABILITY — Technicians are in the field. They need to know: what to check first, what part to swap, what spec to measure, what the failure pattern looks like, what mistake to avoid. Every finding must contain at least one concrete action a tech can take.

5. COVER THESE FINDING TYPES (use as the finding_type field):
   - FAILURE_MODE
   - SERVICE_BULLETIN
   - RECALL
   - REPAIR_TIP
   - WIRING_NOTE
   - CALIBRATION
   - PARTS_SUBSTITUTION
   - INSTALLATION_GOTCHA
   - DIAGNOSTIC_SHORTCUT
   - COMMON_MISDIAGNOSIS
   - KNOWN_ISSUE
   - SAFETY_ALERT

6. SCOPE — Focus exclusively on Range brand appliances. Cover all Range appliance categories represented on Manualslib: ranges, cooktops, ovens, range hoods, etc. If Range appliances share OEM heritage with another brand and that heritage is relevant to a finding (e.g. shared control boards, shared parts), note it.

7. RELEVANCE SCORING — Score each finding 1–10 for field relevance:
   - 10 = Prevents a dangerous misdiagnosis or safety incident, or is an extremely common failure
   - 7–9 = High-frequency failure or time-saving diagnostic shortcut
   - 4–6 = Moderately useful, less common scenario
   - 1–3 = Edge case, low-confidence, or rarely encountered

OUTPUT FORMAT:

Return a JSON array of finding objects. Each object must conform exactly to this shape:

{
  "finding_type": "<one of the types listed above>",
  "brand": "Range",
  "model": "<specific model, model family, or 'All Range [category]' if truly universal>",
  "title": "<short descriptive title, max 12 words>",
  "summary": "<actionable field-ready description, 2–6 sentences, include measurements/specs/part numbers where known>",
  "confidence": "<HIGH | MEDIUM | LOW>",
  "relevance_score": <integer 1–10>
}

Do not include any text outside the JSON array. Do not add commentary, preamble, or closing notes. Do not wrap the JSON in markdown code fences. Return only the raw JSON array.

Begin enumeration now.`;

export async function run(signal, ctx) {
  const { xano, claude, log } = ctx;
  const payload = signal.payload || {};
  const brandHint = payload.brand || '';
  const modelHint = payload.model_number || '';

  const userMessage = [
    'Source: ' + SOURCE_DISPLAY,
    'Appliance category: ' + APPLIANCE_DISPLAY,
    'Brand focus (if any): ' + (brandHint || 'all major brands'),
    'Model focus (if any): ' + (modelHint || 'common consumer models'),
    '',
    'Enumerate 10-20 of the most useful findings this source surfaces',
    'for this appliance type. Return ONLY a JSON array (no commentary)',
    'with objects shaped like:',
    '{',
    '  "finding_type": "service_bulletin" | "common_failure" | "repair_guide" | "forum_thread" | "recall" | "youtube_tip",',
    '  "brand": "<brand or empty>",',
    '  "model": "<model pattern or empty>",',
    '  "title": "<short headline>",',
    '  "summary": "<2-4 sentences of actionable detail a tech could use>",',
    '  "relevance_score": <0-100>',
    '}',
  ].join('\n');

  const resp = await claude.callClaude({
    system: SCOUT_PROMPT,
    messages: [{ role: 'user', content: userMessage }],
    model: config.claudeModel,
    maxTokens: 3000,
  });
  let raw = (claude.textFromResponse ? claude.textFromResponse(resp) : '').trim();
  raw = raw.replace(/^```json/, '').replace(/^```/, '').replace(/```$/, '').trim();

  let findings = [];
  try { findings = JSON.parse(raw); } catch (e) {
    log('scout_parse_failed', { agent_id: AGENT_ID, source: SOURCE_SLUG, appliance: APPLIANCE_SLUG, raw_chars: raw.length });
    await xano.markSignalProcessed(signal.id, 'scout_parse_failed', { agent_id: AGENT_ID, error: 'json_parse' });
    return { success: false, action: 'scout_parse_failed' };
  }
  if (!Array.isArray(findings)) findings = [];

  let saved = 0;
  for (const f of findings) {
    if (!f || !f.summary) continue;
    try {
      await xano.saveModelIntelligenceFinding({
        appliance_model: (f.model || '').toString(),
        appliance_brand: (f.brand || brandHint || '').toString(),
        appliance_category: APPLIANCE_DISPLAY,
        finding_type: (f.finding_type || 'common_failure').toString(),
        source_url: '',
        source_name: SOURCE_DISPLAY,
        title: (f.title || '').toString().slice(0, 200),
        summary: f.summary.toString().slice(0, 2000),
        relevance_score: Number(f.relevance_score || 50),
        scraped_at_ms: Date.now(),
        scout_agent: AGENT_ID,
      });
      saved++;
    } catch (e) {
      log('scout_save_error', { agent_id: AGENT_ID, error: e.message });
    }
  }

  await xano.emitSignal({
    signal_type: 'SCOUT_RUN_COMPLETE',
    signal_strength: 50,
    payload: {
      source: SOURCE_SLUG,
      appliance: APPLIANCE_SLUG,
      findings_saved: saved,
      agent_id: AGENT_ID,
      generated_at_ms: Date.now(),
    },
  });

  const meta = {
    source: SOURCE_SLUG,
    appliance: APPLIANCE_SLUG,
    agent_id: AGENT_ID,
    findings_saved: saved,
    outcome: 'scout_run_complete',
  };
  await xano.markSignalProcessed(signal.id, 'scout_run_complete', meta);
  log('scout_run_complete', meta);

  return { success: true, action: 'scout_run_complete', findings_saved: saved, agent_id: AGENT_ID };
}
